  "computer.introLinux": "Cada bot tiene su propio ordenador Linux: un escritorio completo con navegador, terminal y sus propios archivos, separado de los demás bots y de este servidor. Los ordenadores se duermen cuando no se usan y se despiertan cuando hace falta; no se pierde nada. Puedes mirar o tomar el control en cualquier momento.",
  "computer.introBrowser": "Cada bot tiene su propio navegador en este servidor: una ventana privada que usa para abrir páginas, rellenar formularios y leer lo que hay en pantalla. Puedes mirar o tomar el control en cualquier momento.",
  "computer.noneTitle": "No hay ningún ordenador disponible",
  "computer.noneText": "Los bots todavía no tienen pantalla en este servidor. Quien lo gestiona puede dar a cada bot un ordenador Linux (Docker y la imagen de escritorio) o instalar un motor de navegador. Todo lo demás sigue funcionando.",
