  "computer.footLinux_one": "Borrar elimina ese ordenador con todo lo instalado y guardado en él, salvo los archivos de la biblioteca del bot; la próxima vez se crea uno limpio. Solo puede haber {n} ordenador despierto a la vez: el que lleva más tiempo sin usarse se duerme.",
  "computer.footLinux_other": "Borrar elimina ese ordenador con todo lo instalado y guardado en él, salvo los archivos de la biblioteca del bot; la próxima vez se crea uno limpio. Puede haber hasta {n} ordenadores despiertos a la vez: el que lleva más tiempo sin usarse se duerme.",
  "computer.footBrowser_one": "Reiniciar cierra todas las páginas de ese escritorio y lo deja como nuevo. Solo {n} bot puede tener un escritorio abierto a la vez.",
  "computer.footBrowser_other": "Reiniciar cierra todas las páginas de ese escritorio y lo deja como nuevo. Hasta {n} bots pueden tener un escritorio abierto a la vez.",
  "permissions.intro": "Decisiones permanentes sobre lo que tus bots pueden hacer sin preguntar. Los pagos y las eliminaciones siempre preguntan, y también, después de que un bot haya leído contenido externo, escribir a alguien que nunca has nombrado o actuar en tu propio ordenador, sea lo que sea lo que se guarde aquí.",
  "permissions.emptyTitle": "Ningún permiso guardado",
