  "relay.phoneSteps": "Instala la aplicación Sklubot para Android (Ajustes → General → En tu teléfono), activa su servicio de accesibilidad y, en la aplicación, abre Control del teléfono y activa el relevo: muestra un código que debes escribir arriba. Los bots pueden entonces hacer capturas, tocar, deslizar, escribir y abrir aplicaciones, tras tu sí en el teléfono; nunca comandos. iPhone: no es posible, iOS no lo permite.",
