  "egress.accountIntro": "Los programas del ordenador de un bot pueden llamar a tus API sin tener nunca la clave: actívalo bot por bot (ajustes del bot → Lectura y claves). Sklubot añade la clave fuera del ordenador, solo para los hosts para los que está guardada, y te pregunta antes del primer uso de cada clave.",
