  "recovery.noMailOwner": "Si eres tú: abre un terminal en el contenedor de Sklubot del servidor (con Coolify: tu servicio sklubot → Terminal) y ejecuta este comando con tu dirección. Muestra una contraseña nueva y cierra la sesión en todos los dispositivos.",
