  "smtp.title": "Correos del servidor",
  "smtp.intro": "La cuenta de correo con la que este Sklubot envía sus propios correos: enlaces de «¿Has olvidado tu contraseña?» y cambios de dirección. Solo tú, el propietario del servidor, ves esto.",
  "smtp.statusOn": "Activado: el servidor puede enviar correos.",
