  "backup.title": "Copia de seguridad automática",
  "backup.intro": "Cada noche, el propio Sklubot envía una copia cifrada de sus datos a un almacenamiento S3 fuera de este servidor (OVHcloud, Hetzner, Scaleway…). Solo tú (que gestionas el servidor) ves este ajuste.",
  "backup.statusOn": "Activada: cada noche sale una copia de seguridad.",
  "backup.statusPaused": "En pausa: no hay ninguna copia de seguridad programada.",
  "backup.statusOff": "Sin configurar.",
  "backup.homesNote": "Los ordenadores de los bots no se incluyen: las instalaciones y los inicios de sesión (Claude, ChatGPT…) hay que rehacerlos tras una restauración. El script SSH deploy/backup.sh sí los incluye.",
  "backup.running": "Copia de seguridad en curso: {stage} ({size} enviados)…",
  "backup.stage.starting": "arrancando",
  "backup.stage.database": "copiando la base de datos",
