  "backup.lastFailed": "La última copia falló {when}: {error}",
  "backup.lastGood": "Última copia correcta: {when}.",
  "backup.never": "Todavía no hay ninguna copia de seguridad.",
  "backup.failures": "{n} fallos seguidos: revisa los ajustes y pulsa «Probar la conexión».",
  "backup.next": "Próxima copia: {when}.",
  "backup.runNow": "Hacer una copia ahora",
