  "backup.history": "Historial",
  "backup.byHand": "a mano",
  "backup.scheduled": "programada",
  "backup.inProgress": "en curso…",
  "backup.step1": "La clave de las copias de seguridad",
  "backup.keyWhy": "Las copias se cifran antes de salir de este servidor. Aquí creas una clave de dos partes: la parte pública se queda en el servidor (solo puede cifrar), la parte privada se queda contigo (solo ella puede restaurar). Ni siquiera alguien que se lleve el servidor o el almacenamiento puede leer tus copias.",
  "backup.makeKey": "Crear mi clave de copias de seguridad",
  "backup.noWebCrypto": "Este navegador no puede crear la clave. Abre esta página en un navegador reciente (Chrome, Firefox o Safari actualizados), o pega una clave pública age.",
  "backup.havePublicKey": "Ya tengo una clave age: pegar su clave pública",
  "backup.publicKey": "Clave pública age",
  "backup.publicKeyHint": "Empieza por age1… (age-keygen la muestra). Guarda la clave privada fuera del servidor.",
  "backup.saveKeyTitle": "Guarda ahora esta clave privada.",
  "backup.saveKeyText": "Sin ella, nadie puede restaurar las copias. Descarga el archivo y guárdalo en un lugar seguro (gestor de contraseñas, memoria USB, tu ordenador), no solo en este servidor. No se volverá a mostrar nunca.",
  "backup.download": "Descargar el archivo",
  "backup.copy": "Copiar",
  "backup.keySavedCheck": "He guardado esta clave privada en un lugar seguro, fuera de este servidor.",
  "backup.useKey": "Usar esta clave",
