  "backup.accessKey": "Clave de acceso",
  "backup.secretKey": "Clave secreta",
  "backup.keptHint": "Guardada ({hint})",
  "backup.keysHint": "Cifradas en el servidor, nunca se devuelven al navegador (déjalas vacías para conservar las guardadas). Usa una clave limitada a este bucket si tu proveedor lo permite.",
  "backup.pathStyle": "Dirección de tipo ruta (endpoint/bucket): para MinIO o un nombre de bucket con puntos.",
  "backup.docStart": "Primeros pasos",
  "backup.docEndpoints": "Endpoints por región",
  "backup.docBucket": "Crear un bucket",
  "backup.docKeys": "Crear las claves",
  "backup.guide.ovh.title": "Crear el bucket y las claves en OVHcloud (desde un teléfono)",
  "backup.guide.ovh.1": "Panel de control de OVHcloud → Public Cloud → tu proyecto → Storage → Object Storage.",
  "backup.guide.ovh.2": "Pestaña «Users»: crea un usuario de Object Storage. Anota la clave de acceso y la clave secreta (botón … → «View the secret key»).",
  "backup.guide.ovh.3": "Pestaña «Containers» → «Create an object container»: tipo «S3-compatible API», un nombre en minúsculas (p. ej., sklubot-backups), una región (p. ej., Gravelines = gra), vincula el usuario y luego «Create».",
  "backup.guide.ovh.4": "Aquí: elige la misma región, el nombre del bucket, la clave de acceso y la clave secreta, y luego «Probar la conexión».",
  "backup.guide.hetzner.title": "Crear el bucket y las claves en Hetzner (desde un teléfono)",
  "backup.guide.hetzner.1": "Hetzner Console → tu proyecto → Object Storage → «Create Bucket»: una ubicación (p. ej., Falkenstein = fsn1), un nombre único, visibilidad «private», y luego «Create & Buy now».",
  "backup.guide.hetzner.2": "Menú «Security» → pestaña «S3 Credentials» → «Generate credentials», con una descripción (p. ej., Sklubot).",
  "backup.guide.hetzner.3": "Copia enseguida la clave de acceso (arriba) y la clave secreta (abajo): la clave secreta no se vuelve a mostrar.",
  "backup.guide.hetzner.4": "Aquí: elige la misma ubicación, el nombre del bucket y las dos claves, y luego «Probar la conexión».",
  "backup.guide.scaleway.title": "Crear el bucket y las claves en Scaleway (desde un teléfono)",
  "backup.guide.scaleway.1": "Consola de Scaleway → Object Storage → «+ Create bucket»: una región (p. ej., París = fr-par), un nombre, visibilidad «Private», y luego «Create bucket».",
  "backup.guide.scaleway.2": "Menú de la cuenta (arriba a la derecha) → «IAM & API keys» → pestaña «API keys» → «+ Generate API key».",
  "backup.guide.scaleway.3": "Para Object Storage, elige el proyecto del bucket como proyecto preferido y luego «Generate API key». Copia la clave de acceso y la clave secreta (se muestran una vez).",
  "backup.guide.scaleway.4": "Aquí: elige la misma región, el nombre del bucket y las dos claves, y luego «Probar la conexión».",
  "backup.step3": "Cuándo, y cuántas conservar",
