  "backup.restoreTitle": "Restaurar una copia",
  "backup.restore1": "Necesitas el archivo de tu clave privada, el acceso al almacenamiento y un servidor con Sklubot (aunque esté vacío).",
  "backup.restore2": "En el servidor, con SKLUBOT_S3_ENDPOINT, SKLUBOT_S3_REGION, SKLUBOT_S3_BUCKET, SKLUBOT_S3_PREFIX, SKLUBOT_S3_ACCESS_KEY y SKLUBOT_S3_SECRET_KEY definidos, este comando descarga la última copia y la comprueba:",
