  "lp.what.title": "No es otro chatbot. Son compañeros, con un trabajo de verdad.",
  "lp.what.sub": "Un bot de Sklubot hace más que responder: tiene herramientas, lleva el seguimiento y saca el trabajo adelante de verdad.",
  "lp.f.job.t": "Un trabajo",
  "lp.f.job": "Un rol, instrucciones, habilidades. Escribe su trabajo en unas líneas, o empieza con una plantilla lista.",
  "lp.f.memory.t": "Una memoria",
  "lp.f.memory": "Recuerda lo que le enseñas: tus clientes, tus preferencias, tu forma de escribir. Lees y borras lo que quieras.",
  "lp.f.memory.n1": "Prefiere correos cortos",
  "lp.f.memory.n2": "Cliente clave: Taller Moreau",
  "lp.f.memory.n3": "Reunión de equipo los lunes a las 9",
  "lp.f.voice.t": "Su propia voz",
  "lp.f.voice": "Llama a tu bot y háblale como por teléfono. Te responde en voz alta, con la voz que hayas elegido para él.",
  "lp.f.pc.t": "Su propio ordenador",
  "lp.f.pc": "Un ordenador Linux aislado con navegador, para buscar, rellenar formularios y preparar archivos. Ves su pantalla en directo.",
  "lp.f.pc.pool": "En el plan gratuito, el ordenador se presta para una tarea y luego se borra.",
  "lp.f.pc.task": "Comparar tres presupuestos de envío",
  "lp.f.ok.t": "Tu permiso antes de cualquier cosa irreversible",
  "lp.f.ok": "Enviar, pagar, borrar, publicar: el bot se detiene, te muestra lo que va a hacer y espera. Lo permites una vez, o lo rechazas.",
  "lp.more": "Y además",
  "lp.more.routines": "Rutinas programadas",
  "lp.more.goals": "Objetivos con seguimiento",
  "lp.more.group": "Chats de grupo entre bots",
  "lp.more.apps": "Aplicaciones conectadas",
  "lp.more.pause": "Pausa en cualquier momento",
  "lp.video.captions": "Francés",
  "lp.video.fallback": "Tu navegador no puede reproducir este vídeo: descárgalo aquí.",
  "lp.video.filmLabel": "Vídeo de presentación de Sklubot, 45 segundos, subtitulado",
  "lp.video.usageLabel": "Demo de Sklubot en un minuto: crear una cuenta, elegir una plantilla, hablar con un bot, seguir al mando",
  "lp.film.kicker": "El vídeo",
  "lp.film.title": "Sklubot en 45 segundos.",
  "lp.film.sub": "Tu equipo, su trabajo y tú al mando. Con sonido, o con subtítulos (en francés).",
  "lp.usage.kicker": "Cómo funciona",
  "lp.usage.title": "Instálalo y empieza en 1 minuto.",
  "lp.usage.sub": "Grabado en la aplicación (en francés): crear una cuenta, elegir una plantilla de equipo, escribir a un bot, responder a una petición de aprobación, abrir «Hoy», llamar a un bot.",
  "lp.usage.note": "Grabado en modo demo: las respuestas de los bots son simuladas.",
  "lp.how.s1t": "Crea tu cuenta",
  "lp.how.s1": "Solo hace falta una dirección de correo y una contraseña.",
  "lp.how.s1v": "Solo hace falta una dirección de correo y una contraseña. Confirmas tu dirección con un clic.",
  "lp.how.s2t": "Elige tu equipo",
  "lp.how.s2": "Empieza con una plantilla lista o con un solo asistente, y ponle un nombre.",
  "lp.how.s3t": "Encarga una primera tarea",
  "lp.how.s3": "Escribe como lo harías a un compañero, o llámalo. El bot se pone en marcha, te mantiene informado y pregunta cuando te necesita.",
  "lp.tpl.kicker": "Plantillas",
  "lp.tpl.title": "Equipos listos para empezar.",
  "lp.tpl.sub": "Cada plantilla crea bots prudentes: sus habilidades llegan como borradores y sus rutinas en pausa, hasta que las apruebes.",
  "lp.tpl.bots_one": "{n} bot",
  "lp.tpl.bots_other": "{n} bots",
  "lp.apps.kicker": "Aplicaciones",
  "lp.apps.title": "En tu navegador, en tu PC, en tu bolsillo.",
  "lp.apps.sub": "Una sola cuenta en todas partes: tus bots y tus conversaciones te siguen en todos tus dispositivos.",
  "lp.apps.web.t": "En línea",
  "lp.apps.web": "Nada que instalar. Abre Sklubot en un ordenador, una tableta o un teléfono.",
  "lp.apps.web.meta": "Nada que instalar",
  "lp.apps.windows.t": "Windows",
  "lp.apps.windows": "Una ventana de verdad, notificaciones y el Relais integrado para que tus bots puedan manejar tu PC, solo con tu permiso.",
  "lp.apps.linux.t": "Linux",
  "lp.apps.linux": "Un paquete .deb para Ubuntu y Debian, o un AppImage para los demás.",
  "lp.apps.android.t": "Android",
  "lp.apps.android": "La aplicación para tu teléfono. Al abrirla por primera vez, escribe la dirección de este servidor.",
