  "lp.price.chooseFree": "Empezar gratis",
  "lp.price.all": "Detalles de los precios",
  "lp.trust.kicker": "Confianza",
  "lp.trust.title": "Hecho para que puedas encargarle trabajo de verdad.",
  "lp.trust.t1t": "Cuentas separadas",
  "lp.trust.t1": "Cada cuenta solo ve sus propios bots, archivos y conversaciones. Los ordenadores de los bots son contenedores separados, en una red en la que no pueden verse entre sí.",
  "lp.trust.t2t": "Secretos cifrados",
  "lp.trust.t2": "Las conexiones con aplicaciones y las contraseñas guardadas se cifran en el servidor (AES-256-GCM).",
  "lp.trust.t3t": "Software libre, alojable en Europa",
  "lp.trust.t3": "Sklubot se publica con licencia MIT y funciona en el servidor que elijas, en Francia o en otro lugar de Europa.",
  "lp.trust.t4t": "Tú sigues al mando",
  "lp.trust.t4": "Un registro de cada acción, un botón de Pausa, topes de gasto y tu permiso antes de cualquier cosa que no se pueda deshacer.",
  "lp.faq.kicker": "Preguntas frecuentes",
  "lp.faq.title": "Las preguntas que nos hacen.",
  "lp.faq.q1": "¿Qué es un bot en Sklubot?",
  "lp.faq.a1": "Un asistente de IA con un rol, una memoria, herramientas y, según el plan, un ordenador. Le hablas como a un compañero; también puede trabajar solo, con una rutina programada o hacia un objetivo.",
  "lp.faq.q2": "¿Puede un bot liarla?",
  "lp.faq.a2": "Un bot nuevo es prudente: pregunta antes de actuar. Para todo lo que no se puede deshacer (enviar, pagar, borrar, publicar) se detiene y espera tu permiso, sin «permitir siempre». Puedes pausarlo en cualquier momento.",
  "lp.faq.q3": "¿De verdad puedo hablar con mis bots?",
  "lp.faq.a3": "Sí: llama a un bot desde su conversación y háblale en voz alta. Responde con la voz que hayas elegido para él. También puedes escribirle, cuando quieras.",
  "lp.faq.q4": "¿Tengo que instalar algo?",
  "lp.faq.a4": "No: todo funciona en el navegador, en un ordenador o en un teléfono. Si lo prefieres, hay una aplicación para Windows y Linux, y otra para Android.",
  "lp.faq.q5": "Windows me avisa cuando instalo la aplicación. ¿Es normal?",
  "lp.faq.a5": "Sí. La aplicación todavía no está firmada, así que Windows SmartScreen muestra un aviso la primera vez. Haz clic en «Más información» y luego en «Ejecutar de todas formas». También puedes usar Sklubot en línea, sin instalar nada.",
  "lp.faq.q6": "¿Qué modelos de IA se usan?",
  "lp.faq.a6": "Los modelos de IA que ofrece este servicio, o tu propia clave de API si lo prefieres. Cada bot puede tener su propio modelo y sus modelos de reserva.",
  "lp.faq.q7": "¿Dónde están mis datos?",
  "lp.faq.a7": "En el servidor de este servicio. Desde los ajustes puedes exportar tus datos o eliminar tu cuenta en cualquier momento.",
  "lp.faq.q8": "¿Por qué confirmar mi dirección de correo?",
  "lp.faq.a8": "Para asegurarnos de que eres tú, y para ayudarte si olvidas tu contraseña. Puedes echar un vistazo enseguida; tus bots empiezan a trabajar cuando se confirma.",
  "lp.final.title": "Tu equipo te espera.",
  "lp.final.sub": "Crea tu cuenta, elige una plantilla y encarga una primera tarea.",
  "lp.foot.tag": "Un equipo de bots de IA, con su memoria, sus herramientas, su ordenador y su voz.",
